	t.Parallel()

	statuses := ValidStatuses()
	if len(statuses) != 4 {
		t.Errorf("expected 4 statuses, got %d", len(statuses))
	}
	// Verify lifecycle order
	expected := []Status{StatusDraft, StatusOpen, StatusMerged, StatusClosed}
	for i, s := range expected {
