21	// SSE control events for the agent-native finding stream. Domain events
22	// (for example "session.started" or "comment.created") are emitted as their
23	// code_review_events.event_type values.
24	const (
25		sseEventReady     = "ready"
26		sseEventReconnect = "reconnect"
27		sseEventForbidden = "forbidden"
28		sseEventError     = "error"
29	)
30	
31	// reconnectBackoffInitial / reconnectBackoffCap bound the exponential backoff
32	// used after network errors. The server's max stream duration (~50s) closes
33	// cleanly with an `event: reconnect`; in that case we reconnect immediately
34	// with no backoff.
35	const (
36		reconnectBackoffInitial = 500 * time.Millisecond
37		reconnectBackoffCap     = 30 * time.Second
38	)
