40	func newTrailWatchCmd() *cobra.Command {
41		var (
42			jsonOutput bool
43			showPings  bool
44			once       bool
45			number     int
46		)
47	
48		cmd := &cobra.Command{
49			Use:   "watch [<number>]",
50			Short: "Tail a trail's finding events live",
51			Long: `Subscribe to the trail-scoped agent-native finding SSE stream and
52	print events as they arrive. Reconnects automatically when the server caps the
53	connection (~50s) and on transient network errors.
54	
55	If <number> is omitted, the trail for the current branch is used.
56	
57	This command resolves the trail's id internally and streams
58	GET /api/v1/trails/<id>/reviews/events with Accept: text/event-stream.
59	
60	Events emitted by the server:
61	  ready              initial frame, includes trail and cursor
62	  <event_type>       finding domain event (sessions, findings, suggested changes, ...)
63	  reconnect          server cap reached; re-establishing
64	  forbidden          access was revoked; stream ends
65	  error              server-side error; treated as reconnect`,
66			Args: cobra.MaximumNArgs(1),
67			RunE: func(cmd *cobra.Command, args []string) error {
68				if len(args) == 1 {
69					n, err := strconv.Atoi(args[0])
70					if err != nil || n <= 0 {
71						return fmt.Errorf("invalid trail number %q", args[0])
72					}
73					number = n
74				}
75				return runTrailWatch(cmd, number, jsonOutput, showPings, once)
76			},
77		}
78	
79		cmd.Flags().BoolVar(&jsonOutput, "json", false, "Print each event as a single JSON line")
80		cmd.Flags().BoolVar(&showPings, "show-pings", false, "Print SSE keepalive pings (otherwise suppressed)")
81		cmd.Flags().BoolVar(&once, "once", false, "Open one SSE connection then exit instead of reconnecting")
82	
83		return cmd
84	}
